export function createCommandCode(options = {}) {
    const apiKey = resolveApiKey({ apiKey: options.apiKey, authPaths: options.authPaths });
    if (!apiKey) {
        throw new Error("Command Code API key not found. Set COMMANDCODE_API_KEY env var, create ~/.commandcode/auth.json, or pass apiKey option.");
    }
    return {
        languageModel(modelId) {
            return new CommandCodeLanguageModel(modelId, {
